package com.example.tilecommerce.controller;
import com.example.tilecommerce.dto.AdminDtos.*;import com.example.tilecommerce.entity.*;import com.example.tilecommerce.service.AdminService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin") @RequiredArgsConstructor @PreAuthorize("hasAnyRole('SUPER_ADMIN','SHOP_OWNER')") public class AdminController {private final AdminService s;@GetMapping("/shops") public List<Shop> shops(){return s.shops();}@PostMapping("/shops") @PreAuthorize("hasRole('SUPER_ADMIN')") public Shop shop(@Valid @RequestBody ShopRequest r){return s.shop(r);}@GetMapping("/users") @PreAuthorize("hasRole('SUPER_ADMIN')") public List<User> users(){return s.users();}@PostMapping("/users") @PreAuthorize("hasRole('SUPER_ADMIN')") public User user(@Valid @RequestBody UserRequest r){return s.user(r);}@GetMapping("/categories") public List<Category> categories(){return s.categories();}@PostMapping("/categories") @PreAuthorize("hasRole('SUPER_ADMIN')") public Category category(@Valid @RequestBody CategoryRequest r){return s.category(r);}}
